const aimsFigures = [{"src": "data:image/png;base64,", "caption": "Patent figure 1"}, {"src": "data:image/png;base64,", "caption": "Patent figure 2"}, {"src": "data:image/png;base64,", "caption": "Patent figure 3"}, {"src": "data:image/png;base64,", "caption": "Patent figure 4"}];

